          "title": "第1段 · 篇章精读",
          "html": "<section class=\"revealPart\" id=\"focus-paragraph-1-0\">\n<h3>完整原文 · 第1段</h3>\n<p>In an essay entitled “Making It in America,” the author Adam Davidson relates a joke from cotton country about just how much a modern textile mill has been automated: The average mill has only two employees today, “a man and a dog. The man is there to feed the dog, and the dog is there to keep the man away from the machines.”</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-1\">\n<h3>意群划分 · 第1段</h3>\n<p>In an essay entitled “Making It in America,” the author Adam Davidson relates a joke from cotton country about just how much a modern textile mill has been automated: / The average mill has only two employees today, / “a man and a dog. / The man is there to feed the dog, / and the dog is there to keep the man away from the machines.”</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-2\">\n<h3>意群翻译 · 第1段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">在一篇题为“在美国制造”的文章中，作者亚当·戴维森讲述了一个来自棉花国家的笑话，内容是现代纺织厂的自动化程度 / 如今，工厂平均只有两名员工 / a man and a dog<br>男人是来喂狗的 / 狗的作用是让人类远离机器。”</p>\n</section>",
