          "html": "<section class=\"revealPart\" id=\"focus-paragraph-3-0\">\n<h3>完整原文 · 第3段</h3>\n<p>In the past, workers with average skills, doing an average job, could earn an average lifestyle. But, today, average is officially over. Being average just won’t earn you what it used to. It can’t when so many more employers have so much more access to so much more above average cheap foreign labor, cheap robotics, cheap software, cheap automation and cheap genius. Therefore, everyone needs to find their extra—their unique value contribution that makes them stand out in whatever is their field of employment.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-3-1\">\n<h3>意群划分 · 第3段</h3>\n<p>In the past, / workers with average skills, / doing an average job, / could earn an average lifestyle. / But, / today, / average is officially over. / Being average just won’t earn you what it used to. / It can’t / when so many more employers have so much more access to so much more above average cheap foreign labor, / cheap robotics, / cheap software, / cheap automation and cheap genius. / Therefore, / everyone needs to find their extra—their unique value contribution / that makes them stand out in whatever is their field of employment.</p>\n</section>",
