          "section": 2,
          "title": "第3段 · 句5",
          "html": "<section class=\"revealPart\">\n<h4>句子精析 (5/5)</h4>\n<p style=\"font-family:'Times New Roman',serif;font-size:1.15em;color:#1e293b;line-height:1.7\"><strong>原句：</strong>Therefore, everyone needs to find their extra—their unique value contribution that makes them stand out in whatever is their field of employment.</p>\n<p><strong>意群断句：</strong><code>Therefore, / everyone needs to find their extra—their unique value contribution / that makes them stand out in whatever is their field of employment.</code></p>\n<p style=\"margin:8px 0\"><strong>【意群翻译】：</strong><span style=\"color:#2563eb;font-weight:500;font-size:1.02em\">所以 / 每个人都需要找到自己的额外价值——他们独特的价值贡献 / 这使他们在任何就业领域都能脱颖而出</span></p>\n<div style=\"margin:8px 0;background:#f8fafc;border-left:4px solid #0f766e;padding:8px 12px;border-radius:0 6px 6px 0\">\n  <p style=\"font-weight:bold;color:#0f766e;margin-bottom:4px\">【句法拆解与逻辑剖析】</p>\n  <ul style=\"margin:6px 0 0 18px;padding:0;line-height:1.7;color:#334155\"><li style=\"margin-bottom:5px\"><b>限制性定语从句</b>：关系词 <code>that</code> 引导定语从句修饰先行词 <code>contribution</code>，限定其具体属性与内涵。</li></ul>\n</div>\n<p style=\"margin-top:8px\"><strong>【满分参考汉译】</strong><span style=\"color:#0f766e;font-weight:600;font-size:1.05em\">因此，每个人都需要找到自己的额外价值——独特的价值贡献，使他们在任何就业领域中脱颖而出。</span></p>\n</section>",
