          "html": "<section class=\"revealPart\" id=\"focus-paragraph-5-0\">\n<h3>完整原文 · 第5段</h3>\n<p>There will always be change—new jobs, new products, new services. But the one thing we know for sure is that with each advance in globalization and the I.T. revolution, the best jobs will require workers to have more and better education to make themselves above average.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-5-1\">\n<h3>意群划分 · 第5段</h3>\n<p>There will always be change—new jobs, / new products, / new services. / But the one thing we know for sure is / that with each advance in globalization and the I.T. revolution, / the best jobs will require workers to have more and better education to make themselves above average.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-5-2\">\n<h3>意群翻译 · 第5段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">总会有变化——新的工作 / 新产品 / 新服务<br>但我们确定的一件事是 / 随着全球化和信息技术的每一次进步<br>革命 / 最好的工作需要工人接受更多更好的教育以使自己高于平均水平</p>\n</section>",
