          "section": "先读题干",
          "raw": "## 26题题干\n\n**“Birds of passage” refers to those who ______.**\n\n> “候鸟”是指那些______。\n\n题型：**事实细节题**。\n\n定位预判：**Paragraph 1**\n\n---",
