          "html": "<section class=\"revealPart\" id=\"focus-paragraph-1-0\">\n<h3>完整原文 · 第1段</h3>\n<p>A century ago, the immigrants from across the Atlantic included settlers and sojourners. Along with the many folks looking to make a permanent home in the United States came those who had no intention to stay, and who would make some money and then go home. Between 1908 and 1915, about 7 million people arrived while about 2 million departed. About a quarter of all Italian immigrants, for example, eventually returned to Italy for good. They even had an affectionate nickname, “uccelli di passaggio,” birds of passage.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-1\">\n<h3>意群划分 · 第1段</h3>\n<p>A century ago, / the immigrants from across the Atlantic included settlers and sojourners. / Along with the many folks looking to make a permanent home in the United States came those / who had no intention to stay, / and / who would make some money and then go home. / Between 1908 and 1915, / about 7 million people arrived / while about 2 million departed. / About a quarter of all Italian immigrants, / for example, / eventually returned to Italy for good. / They even had an affectionate nickname, / “uccelli di passaggio,” birds of passage.</p>\n</section>",
