          "title": "第1段 · 篇章精读",
          "html": "<section class=\"revealPart\" id=\"focus-paragraph-1-0\">\n<h3>完整原文 · 第1段</h3>\n<p>A century ago, the immigrants from across the Atlantic included settlers and sojourners. Along with the many folks looking to make a permanent home in the United States came those who had no intention to stay, and who would make some money and then go home. Between 1908 and 1915, about 7 million people arrived while about 2 million departed. About a quarter of all Italian immigrants, for example, eventually returned to Italy for good. They even had an affectionate nickname, “uccelli di passaggio,” birds of passage.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-1\">\n<h3>意群划分 · 第1段</h3>\n<p>A century ago, / the immigrants from across the Atlantic included settlers and sojourners. / Along with the many folks looking to make a permanent home in the United States came those / who had no intention to stay, / and / who would make some money and then go home. / Between 1908 and 1915, / about 7 million people arrived / while about 2 million departed. / About a quarter of all Italian immigrants, / for example, / eventually returned to Italy for good. / They even had an affectionate nickname, / “uccelli di passaggio,” birds of passage.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-2\">\n<h3>意群翻译 · 第1段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">一个世纪前 / 来自大西洋彼岸的移民包括定居者和寄居者<br>与许多希望在美国永久定居的人一起到来的是 / 谁无意留下来 / 和 / 谁会赚一些钱然后回家<br>1908 年至 1915 年间 / 约700万人抵达 / 而大约200万人离开<br>约占所有意大利移民的四分之一 / 例如 / 最终永久返回意大利<br>他们甚至还有一个亲切的绰号 / uccelli di passaggio,” birds of passage</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-3\">\n<h3>标准译文 · 第1段</h3>\n<p>一个世纪前，来自大西洋彼岸的移民包括定居者和寄居者。除了许多希望在美国永久定居的人之外，还有一些无意留下来、想赚点钱然后回家的人。 1908 年至 1915 年间，约有 700 万人抵达，约 200 万人离开。例如，大约四分之一的意大利移民最终永久返回意大利。它们甚至还有一个亲切的昵称“uccelli di passaggio”，即候鸟。</p>\n</section>",
