          "html": "<section class=\"revealPart\" id=\"focus-paragraph-3-0\">\n<h3>完整原文 · 第3段</h3>\n<p>Crop pickers, violinists, construction workers, entrepreneurs, engineers, home health-care aides and physicists are among today’s birds of passage. They are energetic participants in a global economy driven by the flow of work, money and ideas. They prefer to come and go as opportunity calls them. They can manage to have a job in one place and a family in another. With or without permission, they straddle laws, jurisdictions and identities with ease. We need them to imagine the United States as a place where they can be productive for a while without committing themselves to staying forever. We need them to feel that home can be both here and there and that they can belong to two nations honorably.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-3-1\">\n<h3>意群划分 · 第3段</h3>\n<p>Crop pickers, / violinists, / construction workers, / entrepreneurs, / engineers, / home health-care aides and physicists are among today’s birds of passage. / They are energetic participants in a global economy driven by the flow of work, / money and ideas. / They prefer to come and go as opportunity calls them. / They can manage to have a job in one place and a family in another. / With or without permission, / they straddle laws, / jurisdictions and identities with ease. / We need them to imagine the United States as a place / where they can be productive for a / while without committing themselves to staying forever. / We need them to feel / that home can be both here and there and / that they can belong to two nations honorably.</p>\n</section>",
