          "section": 2,
          "title": "第1段 · 篇章精读",
          "html": "<section class=\"revealPart\" id=\"focus-paragraph-1-0\">\n<h3>完整原文 · 第1段</h3>\n<p>Scientists have found that although we are prone to snap overreactions, if we take a moment and think about how we are likely to react, we can reduce or even eliminate the negative effects of our quick, hard-wired responses.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-1\">\n<h3>意群划分 · 第1段</h3>\n<p>Scientists have found / that although we are prone to snap overreactions, / / if we take a moment and think about how we are likely to react, / we can reduce or even eliminate the negative effects of our quick, / hard-wired responses.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-2\">\n<h3>意群翻译 · 第1段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">科学家发现 / 尽管我们容易反应过度 / 如果我们花点时间思考一下我们可能会如何反应 / 我们可以减少甚至消除我们快速行动的负面影响 / 硬连线响应</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-3\">\n<h3>标准译文 · 第1段</h3>\n<p>科学家发现，虽然我们很容易做出过度反应，但如果我们花点时间思考一下我们可能会如何反应，我们就可以减少甚至消除快速、固有反应的负面影响。</p>\n</section>",
