          "html": "<section class=\"revealPart\" id=\"focus-paragraph-3-0\">\n<h3>完整原文 · 第3段</h3>\n<p>But snap decisions in reaction to rapid stimuli aren’t exclusive to the interpersonal realm. Psychologists at the University of Toronto found that viewing a fast-food logo for just a few milliseconds primes us to read 20 percent faster, even though reading has little to do with eating. We unconsciously associate fast food with speed and impatience and carry those impulses into whatever else we’re doing. Subjects exposed to fast-food flashes also tend to think a musical piece lasts too long.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-3-1\">\n<h3>意群划分 · 第3段</h3>\n<p>But snap decisions in reaction to rapid stimuli aren’t exclusive to the interpersonal realm. / Psychologists at the University of Toronto found / that viewing a fast-food logo for just a few milliseconds primes us to read 20 percent faster, / even / though reading has little to do with eating. / We unconsciously associate fast food with speed and impatience and carry those impulses into whatever else we’re doing. / Subjects exposed to fast-food flashes also tend to think a musical piece lasts too long.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-3-2\">\n<h3>意群翻译 · 第3段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">但对快速刺激作出反应的仓促决定并不只存在于人际领域<br>多伦多大学心理学家发现 / 只需查看快餐标志几毫秒，我们的阅读速度就会加快 20% / 甚至 / 虽然读书和吃饭关系不大<br>我们无意识地将快餐与速度和不耐烦联系在一起，并将这些冲动带入我们正在做的其他事情中<br>接触快餐闪光灯的受试者也倾向于认为音乐作品持续时间太长</p>\n</section>",
