          "html": "<div class=\"coarseStack\"><div class=\"coarsePara currentFocus\"><p>【第1段意群顺译】欧洲不是性别平等的天堂。特别是，除非女性参与高级管理决策，否则企业工作场所永远不会完全适合家庭，而欧洲企业最高治理职位仍然绝大多数是男性。事实上，女性在欧洲公司董事会中只占 14% 的职位。...</p></div></div>",
