          "section": 2,
          "title": "第2段 · 篇章精读",
          "html": "<section class=\"revealPart\" id=\"focus-paragraph-2-0\">\n<h3>完整原文 · 第2段</h3>\n<p>The European Union is now considering legislation to compel corporate boards to maintain a certain proportion of women—up to 60 per cent. This proposed mandate was born of frustration. Last year, European Commission Vice President Viviane Reding issued a call to voluntary action. Reding invited corporations to sign up for gender balance goals of 40 percent female board membership. But her appeal was considered a failure: only 24 companies took it up.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-2-1\">\n<h3>意群划分 · 第2段</h3>\n<p>The European Union is now considering legislation to compel corporate boards to maintain a certain proportion of women—up to 60 per cent. / This proposed mandate was born of frustration. / Last year, / European Commission Vice President Viviane Reding issued a call to voluntary action. / Reding invited corporations to sign up for gender balance goals of 40 percent female board membership. / But her appeal was considered a failure: / only 24 companies took it up.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-2-2\">\n<h3>意群翻译 · 第2段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">欧盟目前正在考虑立法强制公司董事会维持一定比例的女性——高达 60%<br>这项拟议的任务是出于挫败感而产生的<br>去年 / 欧盟委员会副主席维维安·雷丁呼吁采取自愿行动<br>Reding 邀请企业签署 40% 女性董事会成员的性别平衡目标<br>但她的上诉被认为失败了 / 只有24家公司接受了它</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-2-3\">\n<h3>标准译文 · 第2段</h3>\n<p>欧盟目前正在考虑立法强制公司董事会保留一定比例的女性成员——最高可达 60%。这项拟议的任务授权是出于挫败感。去年，欧盟委员会副主席维维安·雷丁呼吁采取自愿行动。雷丁邀请企业签署性别平衡目标，即董事会女性成员比例达到 40%。但她的上诉被认为失败了：只有 24 家公司接受了她的上诉。</p>\n</section>",
