          "html": "<section class=\"revealPart\" id=\"focus-paragraph-5-0\">\n<h3>完整原文 · 第5段</h3>\n<p>I understand Reding’s reluctance—and her frustration. I don’t like quotas either; they run counter to my belief in meritocracy, governance by the capable. But, when one considers the obstacles to achieving the meritocratic ideal, it does look as if a fairer world must be temporarily ordered.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-5-1\">\n<h3>意群划分 · 第5段</h3>\n<p>I understand Reding’s reluctance—and her frustration. / I don’t like quotas either; / they run counter to my belief in meritocracy, / governance by the capable. / But, / / when one considers the obstacles to achieving the meritocratic ideal, / it does look as / if a fairer world must be temporarily ordered.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-5-2\">\n<h3>意群翻译 · 第5段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">我理解雷丁的不情愿和她的沮丧<br>我也不喜欢配额 / 它们与我对精英管理的信念背道而驰 / 有能力的人治理<br>但 / 当人们考虑实现精英理想的障碍时 / 它看起来确实像 / 如果必须暂时建立一个更公平的世界</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-5-3\">\n<h3>标准译文 · 第5段</h3>\n<p>我理解雷丁的不情愿和她的沮丧。我也不喜欢配额；它们与我对精英统治、有能力者治理的信念背道而驰。但是，当人们考虑到实现精英理想的障碍时，看起来确实必须暂时建立一个更加公平的世界。</p>\n</section>",
